"use strict";(globalThis.webpackChunkrockit_documentation=globalThis.webpackChunkrockit_documentation||[]).push([[4539],{2950(e,a,t){t.r(a),t.d(a,{assets:()=>l,contentTitle:()=>i,default:()=>m,frontMatter:()=>o,metadata:()=>s,toc:()=>k});const s=JSON.parse('{"id":"history/history","title":"T\xf6rt\xe9neti \xe1ttekint\xe9s","description":"Ny\xedlt tudom\xe1ny (Open Science)","source":"@site/docs/common/history/history.md","sourceDirName":"history","slug":"/history/","permalink":"/RocKIT/history/","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":2,"frontMatter":{"sidebar_position":2},"sidebar":"appSidebar","previous":{"title":"RocKIT \u2013 RO-Crate Kit","permalink":"/RocKIT/"},"next":{"title":"RO-Crate gyorstalpal\xf3","permalink":"/RocKIT/ro-crate-in-nutshell/"}}');var n=t(4848),r=t(8453);const o={sidebar_position:2},i="T\xf6rt\xe9neti \xe1ttekint\xe9s",l={},k=[{value:"Ny\xedlt tudom\xe1ny (Open Science)",id:"ny\xedlt-tudom\xe1ny-open-science",level:2},{value:"Adatrepozit\xf3riumok",id:"adatrepozit\xf3riumok",level:2},{value:"FAIR ir\xe1nyelvek",id:"fair-ir\xe1nyelvek",level:2},{value:"FAIR digit\xe1lis objektumok",id:"fair-digit\xe1lis-objektumok",level:2},{value:"RO-Crate",id:"ro-crate",level:2},{value:"Az RO-Crate \xe9s az adatrepozit\xf3riumok kapcsolata",id:"az-ro-crate-\xe9s-az-adatrepozit\xf3riumok-kapcsolata",level:2},{value:"ARP adatrepozit\xf3rium, AROMA-1",id:"arp-adatrepozit\xf3rium-aroma-1",level:2}];function z(e){const a={a:"a",h1:"h1",h2:"h2",header:"header",p:"p",...(0,r.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(a.header,{children:(0,n.jsx)(a.h1,{id:"t\xf6rt\xe9neti-\xe1ttekint\xe9s",children:"T\xf6rt\xe9neti \xe1ttekint\xe9s"})}),"\n",(0,n.jsx)(a.h2,{id:"ny\xedlt-tudom\xe1ny-open-science",children:"Ny\xedlt tudom\xe1ny (Open Science)"}),"\n",(0,n.jsx)(a.p,{children:"A kutat\xe1si adatok egy r\xe9sze k\xf6zp\xe9nzb\u0151l sz\xe1rmazik. Ezen kutat\xe1si adatok eset\xe9ben jogos lehet az ig\xe9ny arra, hogy ne csak az azokat el\u0151\xe1ll\xedt\xf3k f\xe9rjenek hozz\xe1juk, hanem mindenki m\xe1s is, aki b\xe1rmi form\xe1ban (p\xe9ld\xe1ul ad\xf3fizet\xe9s\r\n\xfatj\xe1n) finansz\xedrozza ezek el\u0151\xe1ll\xedt\xe1s\xe1t. A nem k\xf6zp\xe9nzb\u0151l keletkez\u0151 adatok eset\xe9n is felmer\xfclhet az ig\xe9ny arra, hogy azok sz\xe9lesebb k\xf6rben is hozz\xe1f\xe9rhet\u0151ek legyenek. Az Open Science mozgalom a fentiek biztos\xedt\xe1s\xe1t, a kutat\xe1si adatok \xe9s az azokon alapul\xf3 publik\xe1ci\xf3k ny\xedlt, kontroll\xe1lt k\xf6zz\xe9t\xe9tel\xe9t t\u0171zte ki c\xe9lj\xe1ul. A kutat\xe1si adatok k\xf6zz\xe9t\xe9tel\xe9hez megfelel\u0151 infrastrukt\xfar\xe1t adnak az adatrepozit\xf3riumok."}),"\n",(0,n.jsx)(a.h2,{id:"adatrepozit\xf3riumok",children:"Adatrepozit\xf3riumok"}),"\n",(0,n.jsx)(a.p,{children:"Az adatrepozit\xf3riumok adatok/kutat\xe1si adatok, menedzsel\xe9s\xe9re, hossz\xfa t\xe1v\xfa t\xe1rol\xe1s\xe1ra, k\xf6zread\xe1s\xe1ra szolg\xe1lnak.\r\nAz adatrepozit\xf3riumok k\xe9t nagy t\xedpusa: a generikus \xe9s a t\xe9maspecifikus adatrepozit\xf3riumok. El\u0151bbiek t\xf6bb tudom\xe1nyter\xfclet, ut\xf3bbiak egy adott tudom\xe1nyter\xfclet adataira specializ\xe1l\xf3dnak. A generikus adatrepozit\xf3riumok a felt\xf6lt\xf6tt adatokat, f\xe1jlokat adatcsomagok form\xe1j\xe1ban  strukt\xfar\xe1ba rendezve t\xe1rolj\xe1k. Az adatcsomagokhoz szerkeszt\xe9si, megtekint\xe9si jogosults\xe1gokat t\xe1rs\xedtanak, verzi\xf3kat kezelnek, permanens azonos\xedt\xf3kat rendelnek hozz\xe1juk. Az adatcsomagok alapvet\u0151en arra szolg\xe1lnak, hogy publik\xe1ci\xf3k eredm\xe9nyeit al\xe1t\xe1massz\xe1k, a publik\xe1ci\xf3kban szerepl\u0151 \xe1ll\xedt\xe1sok ellen\u0151rizhet\u0151ek, a k\xeds\xe9rletek megism\xe9telhet\u0151ek legyenek."}),"\n",(0,n.jsx)(a.h2,{id:"fair-ir\xe1nyelvek",children:"FAIR ir\xe1nyelvek"}),"\n",(0,n.jsx)(a.p,{children:"A FAIR ir\xe1nyelvek egyre ink\xe1bb el\u0151t\xe9rbe ker\xfclnek. A bet\u0171sz\xf3 a Findable, Accessible, Interoperable \xe9s\r\nReusable angol szavak kezd\u0151bet\u0171ib\u0151l \xe1ll \xf6ssze. A FAIR alapelvek szerint a kutat\xe1si adatoknak ahhoz, hogy a kutat\xe1s tisztas\xe1ga \xe9s ellen\u0151rizhet\u0151s\xe9ge biztos\xedtva legyen, megtal\xe1lhat\xf3nak, egyszer\u0171 eszk\xf6z\xf6kkel hozz\xe1f\xe9rhet\u0151nek \xe9s feldolgozhat\xf3nak kell lenni\xfck, valamint a kutat\xe1si eredm\xe9nyekhez vezet\u0151 \xfat ellen\u0151rizhet\u0151 m\xf3don megism\xe9telhet\u0151 kell, hogy legyen. Az Open Science kezdem\xe9nyez\xe9s \xf6r\xf6mmel t\u0171zte z\xe1szlaj\xe1ra ezeket az elveket, hiszen leegyszer\u0171s\xedtik a m\xe1r publik\xe1l\xe1sra ker\xfclt adatok feldolgoz\xe1s\xe1t minden hozz\xe1\xe9rt\u0151 szem\xe9ly sz\xe1m\xe1ra (m\xe9g akkor is, ha a FAIR ir\xe1nyelvek k\xf6vet\xe9se nem garant\xe1lja a kutat\xe1si adatok k\xf6zkinccs\xe9 t\xe9tel\xe9t). Az ir\xe1nyelvek teljes\xfcl\xe9s\xe9t az emberi feldolgoz\xe1s mellett az automatikus eszk\xf6z\xf6k sz\xe1m\xe1ra is biztos\xedtani kell, ut\xf3bbiak eset\xe9ben k\xfcl\xf6n\xf6sen a hozz\xe1f\xe9rhet\u0151s\xe9get \xe9s esetenk\xe9nt az automatikus feldolgozhat\xf3s\xe1got. Ez ut\xf3bbi kit\xe9tel megval\xf3sul\xe1sa a kutat\xe1si adatok olyan szemantikus c\xedmk\xe9z\xe9s\xe9t felt\xe9telezi, amely a jelenleg haszn\xe1lt adatrepozit\xf3riumokban nem, vagy csak nagyon sok kompromisszum \xe1r\xe1n val\xf3sulhat meg."}),"\n",(0,n.jsx)(a.h2,{id:"fair-digit\xe1lis-objektumok",children:"FAIR digit\xe1lis objektumok"}),"\n",(0,n.jsx)(a.p,{children:"Az Eur\xf3pai Uni\xf3 egy akci\xf3tervben 2018-ban bevezette a FAIR Digit\xe1lis Objektumok fogalm\xe1t. A FAIR Digit\xe1lis Objektumok (FAIR Digital Object - FDO) olyan digit\xe1lis objektumok, amelyek adott k\xf6rnyezetben megfelelnek a FAIR ir\xe1nyelveknek: \u201eAz adatok, szoftver \xe9s m\xe1s er\u0151forr\xe1sok reprezent\xe1ci\xf3ja.\u201d... \u201eT\xe1rs\xedtva vannak hozz\xe1 perzisztens\r\nazonos\xedt\xf3k, metaadatok \xe9s kontextu\xe1lis dokument\xe1ci\xf3, ami lehet\u0151v\xe9 teszi a felder\xedthet\u0151s\xe9get, id\xe9z\xe9st \xe9s\r\n\xfajrahasznos\xedt\xe1st.\u201d"}),"\n",(0,n.jsx)(a.p,{children:"A defin\xedci\xf3 alapj\xe1n az FDO-nak az adott digit\xe1lis k\xf6rnyezetben meg kell tudnia mondani mag\xe1r\xf3l mind emberek, mind automatikus feldolgoz\xf3 eszk\xf6z\xf6k sz\xe1m\xe1ra, hogy mi is val\xf3j\xe1ban. Az \xfajrahasznos\xedt\xe1s \xe9s reproduk\xe1lhat\xf3s\xe1g krit\xe9riuma miatt az adatrepozit\xf3riumoknak olyan szint\u0171 metaadatol\xe1st kell biztos\xedtaniuk, amivel form\xe1lisan meghat\xe1rozhat\xf3ak a kutat\xe1si adatok feldolgoz\xe1s\xe1hoz sz\xfcks\xe9ges l\xe9p\xe9sek, valamint megjel\xf6lhet\u0151k mind a forr\xe1sadatok, mind a feldolgoz\xe1s eredm\xe9nye. E krit\xe9rium olyan terhet r\xf3 az egyszer\u0171 generikus adatrepozit\xf3riumokra, amely nehezen teljes\xedthet\u0151, azokban ugyanis a repozit\xe1l\xe1s \xe9s a form\xe1lis metaadatol\xe1s szintje jellemz\u0151en az adatcsomag, amiben az egyes f\xe1jlokr\xf3l neh\xe9z meg\xe1llap\xedt\xe1sokat tenni."}),"\n",(0,n.jsx)(a.h2,{id:"ro-crate",children:"RO-Crate"}),"\n",(0,n.jsxs)(a.p,{children:["Az RO-Crate (Research Object Crate) csomagol\xe1stechnika az FDO egy lehets\xe9ges megval\xf3s\xedt\xe1sa, amely az\r\n",(0,n.jsx)(a.a,{href:"https://science-research-data.hu/",children:"ELKH ARP"})," projekt sor\xe1n a FAIR ir\xe1nyelvek t\xe1mogat\xe1s\xe1ra ker\xfclt kiv\xe1laszt\xe1sra. Felhaszn\xe1l\xf3i szemmel az RO-Crate adatcsomag: f\xe1jlok \xe9s URI-kon kereszt\xfcl megc\xedmezhet\u0151 objektumok olyan hierarchikus strukt\xfar\xe1ja (egyszer\u0171bben: k\xf6nyvt\xe1rakba rendezett f\xe1jlok \xe9s hivatkoz\xe1sok), amelyben minden elemhez (vagyis a teljes adatcsomaghoz, a k\xf6nyvt\xe1rakhoz, a f\xe1jlokhoz \xe9s a hivatkoz\xe1sokhoz) le\xedr\xf3 adatokat, metaadatokat lehet rendelni. Ezzel megval\xf3sulhat, hogy form\xe1lisan b\xe1rmely f\xe1jlhoz hozz\xe1 lehet csatolni,  keletkez\xe9s\xe9nek \xe9s tartalm\xe1nak inform\xe1ci\xf3it. Az RO-Crate adatcsomag a f\xe1jlstrukt\xfara \xe9s az annak elemeit le\xedr\xf3 metaadatok k\xf6t\xf6tt form\xe1j\xfa f\xe1jlba csomagolt v\xe1ltozata."]}),"\n",(0,n.jsx)(a.h2,{id:"az-ro-crate-\xe9s-az-adatrepozit\xf3riumok-kapcsolata",children:"Az RO-Crate \xe9s az adatrepozit\xf3riumok kapcsolata"}),"\n",(0,n.jsx)(a.p,{children:"Egy tetsz\u0151leges RO-Crate adatcsomag, mint adatf\xe1jl, felt\xf6lthet\u0151 a generikus repozit\xf3riumokba. Ilyenkor l\xe9trej\xf6n egy adatcsomag, aminek a tartalma a felt\xf6lt\xf6tt RO-Crate adatcsomag, amelyben lehet\u0151s\xe9g van annak metaadatokkal val\xf3 ell\xe1t\xe1s\xe1ra. Az RO-Crate adatcsomag megtestes\xedti egy kutat\xe1s teljes publik\xe1l\xe1sra sz\xe1nt adathalmaz\xe1t, azaz az RO-Crate adatcsomag eg\xe9sz\xe9re vonatkoz\xf3 metaadatoknak \xe9s a repozit\xf3riumokba ker\xfcl\u0151 adatcsomagra vonatkoz\xf3 metaadatoknak meg kellene egyezni\xfck, hiszen ebben az \xe9rtelemben ugyanazt \xedrj\xe1k le. Erre vonatkoz\xf3 t\xe1mogat\xe1s azonban nincsen az adatrepozit\xf3riumokban. Fontos tudni azt is, hogy az \xedgy felt\xf6lt\xf6tt RO-Crate csomag hi\xe1ba szolg\xe1ltathatna f\xe1jlszint\u0171 metaadatokat, az adatok tov\xe1bbra is csak a repozit\xf3riumba k\xf6zvetlen\xfcl bevitt, adatcsomagszint\u0171 metaadatokon kereszt\xfcl lesznek kereshet\u0151ek."}),"\n",(0,n.jsx)(a.h2,{id:"arp-adatrepozit\xf3rium-aroma-1",children:"ARP adatrepozit\xf3rium, AROMA-1"}),"\n",(0,n.jsxs)(a.p,{children:["Az ARP projekt az ",(0,n.jsx)(a.a,{href:"https://www.elkh.org/",children:"ELKH"})," t\xe1mogat\xe1s\xe1val \xfaj adatrepozit\xf3riumot fejlesztett.\r\nAz \xfaj generikus adatrepozit\xf3rium a Harvard Dataverse tov\xe1bbfejleszt\xe9se, amely az egyszer\u0171 f\xe1jlfelt\xf6lt\xe9st meghalad\xf3an t\xe1mogatja az RO-Crate adatcsomagok kezel\xe9s\xe9t is. Lehets\xe9ges benne az RO-Crate adatcsomagok importja, exportja, valamint a helyben t\xf6rt\xe9n\u0151 szerkeszt\xe9se - \xfagy, hogy b\xe1rmely m\u0171velet elv\xe9gz\xe9se sor\xe1n az RO-Crate eg\xe9sz\xe9re, valamint az adatrepozit\xf3riumi adatcsomagra vonatkoz\xf3 adatok szinkronban maradnak. A f\xe1jlszint\u0171 metaadatszerkeszt\xe9s integr\xe1lt eszk\xf6ze az AROMA-1 (ARP RO-Crate Manager) szoftverkomponens."]})]})}function m(e={}){const{wrapper:a}={...(0,r.R)(),...e.components};return a?(0,n.jsx)(a,{...e,children:(0,n.jsx)(z,{...e})}):z(e)}},8453(e,a,t){t.d(a,{R:()=>o,x:()=>i});var s=t(6540);const n={},r=s.createContext(n);function o(e){const a=s.useContext(r);return s.useMemo(function(){return"function"==typeof e?e(a):{...a,...e}},[a,e])}function i(e){let a;return a=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:o(e.components),s.createElement(r.Provider,{value:a},e.children)}}}]);